SELECT ?root ?status ?implementation ?design ?route ?verification ?verification_status ?result ?definition_revision ?applicable ?implementation_edges ?execution_edges ?execution_facts WHERE {
?root <urn:mara:field:status> ?status .

OPTIONAL { ?root <urn:mara:query:input:implementation> ?implementation_row .
OPTIONAL { ?implementation_row <urn:mara:query:column:implementation:implementation> ?implementation }
OPTIONAL { ?implementation_row <urn:mara:query:column:implementation:design> ?design }
OPTIONAL { ?implementation_row <urn:mara:query:column:implementation:route> ?route }
OPTIONAL { ?implementation_row <urn:mara:query:column:implementation:implementation_edges> ?implementation_edges }
}
OPTIONAL { ?root <urn:mara:query:input:execution> ?execution_row .
OPTIONAL { ?execution_row <urn:mara:query:column:execution:verification> ?verification }
OPTIONAL { ?execution_row <urn:mara:query:column:execution:verification_status> ?verification_status }
OPTIONAL { ?execution_row <urn:mara:query:column:execution:result> ?result }
OPTIONAL { ?execution_row <urn:mara:query:column:execution:definition_revision> ?definition_revision }
OPTIONAL { ?execution_row <urn:mara:query:column:execution:applicable> ?applicable }
OPTIONAL { ?execution_row <urn:mara:query:column:execution:execution_edges> ?execution_edges }
OPTIONAL { ?execution_row <urn:mara:query:column:execution:execution_facts> ?execution_facts }
}
}

SELECT ?root ?status ?basis_status ?definition_status ?implementation ?design ?route ?verification ?verification_status ?result ?definition_revision ?applicable ?risk ?threatened ?level ?risk_accepted ?knowledge_edges ?implementation_edges ?execution_edges ?risk_edges ?execution_facts WHERE {
?root <urn:mara:field:status> ?status .

OPTIONAL { ?root <urn:mara:query:input:knowledge> ?knowledge_row .
OPTIONAL { ?knowledge_row <urn:mara:query:column:knowledge:basis_status> ?basis_status }
OPTIONAL { ?knowledge_row <urn:mara:query:column:knowledge:definition_status> ?definition_status }
OPTIONAL { ?knowledge_row <urn:mara:query:column:knowledge:knowledge_edges> ?knowledge_edges }
}
OPTIONAL { ?root <urn:mara:query:input:implementation> ?implementation_row .
OPTIONAL { ?implementation_row <urn:mara:query:column:implementation:implementation> ?implementation }
OPTIONAL { ?implementation_row <urn:mara:query:column:implementation:design> ?design }
OPTIONAL { ?implementation_row <urn:mara:query:column:implementation:route> ?route }
OPTIONAL { ?implementation_row <urn:mara:query:column:implementation:implementation_edges> ?implementation_edges }
}
OPTIONAL { ?root <urn:mara:query:input:execution> ?execution_row .
OPTIONAL { ?execution_row <urn:mara:query:column:execution:verification> ?verification }
OPTIONAL { ?execution_row <urn:mara:query:column:execution:verification_status> ?verification_status }
OPTIONAL { ?execution_row <urn:mara:query:column:execution:result> ?result }
OPTIONAL { ?execution_row <urn:mara:query:column:execution:definition_revision> ?definition_revision }
OPTIONAL { ?execution_row <urn:mara:query:column:execution:applicable> ?applicable }
OPTIONAL { ?execution_row <urn:mara:query:column:execution:execution_edges> ?execution_edges }
OPTIONAL { ?execution_row <urn:mara:query:column:execution:execution_facts> ?execution_facts }
}
OPTIONAL { ?root <urn:mara:query:input:risk> ?risk_row .
OPTIONAL { ?risk_row <urn:mara:query:column:risk:risk> ?risk }
OPTIONAL { ?risk_row <urn:mara:query:column:risk:threatened> ?threatened }
OPTIONAL { ?risk_row <urn:mara:query:column:risk:level> ?level }
OPTIONAL { ?risk_row <urn:mara:query:column:risk:risk_accepted> ?risk_accepted }
OPTIONAL { ?risk_row <urn:mara:query:column:risk:risk_edges> ?risk_edges }
}
}

SELECT ?root ?status ?mitigation ?acceptance ?risk ?risk_status ?target ?ancestor ?context_kind ?likelihood ?consequence ?level ?risk_accepted ?relevance_edges ?assessment_edges WHERE {
?root <urn:mara:field:status> ?status .

OPTIONAL { ?root <urn:mara:query:input:relevance> ?relevance_row .
OPTIONAL { ?relevance_row <urn:mara:query:column:relevance:risk> ?risk }
OPTIONAL { ?relevance_row <urn:mara:query:column:relevance:risk_status> ?risk_status }
OPTIONAL { ?relevance_row <urn:mara:query:column:relevance:target> ?target }
OPTIONAL { ?relevance_row <urn:mara:query:column:relevance:ancestor> ?ancestor }
OPTIONAL { ?relevance_row <urn:mara:query:column:relevance:context_kind> ?context_kind }
OPTIONAL { ?relevance_row <urn:mara:query:column:relevance:relevance_edges> ?relevance_edges }
}
OPTIONAL { ?root <urn:mara:query:input:assessment> ?assessment_row .
?assessment_row <urn:mara:query:column:assessment:risk> ?risk .
OPTIONAL { ?assessment_row <urn:mara:query:column:assessment:likelihood> ?likelihood }
OPTIONAL { ?assessment_row <urn:mara:query:column:assessment:consequence> ?consequence }
OPTIONAL { ?assessment_row <urn:mara:query:column:assessment:level> ?level }
OPTIONAL { ?assessment_row <urn:mara:query:column:assessment:risk_accepted> ?risk_accepted }
OPTIONAL { ?assessment_row <urn:mara:query:column:assessment:assessment_edges> ?assessment_edges }
}
OPTIONAL { FILTER(BOUND(?risk)) ?mitigation <urn:mara:relation:mitigates> ?risk }
OPTIONAL { FILTER(BOUND(?risk)) ?acceptance <urn:mara:relation:accepts> ?risk }
}

SELECT ?root ?status ?decision ?evidence ?requirement_basis ?requirement_relation ?requirement_basis_status ?design_basis ?design_relation ?design_basis_status ?requirement_basis_edges ?design_basis_edges WHERE {
?root <urn:mara:field:status> ?status .
OPTIONAL { ?decision <urn:mara:relation:justifies> ?root } OPTIONAL { ?evidence <urn:mara:relation:supports> ?root }
OPTIONAL { ?root <urn:mara:query:input:requirement_basis> ?requirement_basis_row .
OPTIONAL { ?requirement_basis_row <urn:mara:query:column:requirement_basis:requirement_basis> ?requirement_basis }
OPTIONAL { ?requirement_basis_row <urn:mara:query:column:requirement_basis:requirement_relation> ?requirement_relation }
OPTIONAL { ?requirement_basis_row <urn:mara:query:column:requirement_basis:requirement_basis_status> ?requirement_basis_status }
OPTIONAL { ?requirement_basis_row <urn:mara:query:column:requirement_basis:requirement_basis_edges> ?requirement_basis_edges }
}
OPTIONAL { ?root <urn:mara:query:input:design_basis> ?design_basis_row .
OPTIONAL { ?design_basis_row <urn:mara:query:column:design_basis:design_basis> ?design_basis }
OPTIONAL { ?design_basis_row <urn:mara:query:column:design_basis:design_relation> ?design_relation }
OPTIONAL { ?design_basis_row <urn:mara:query:column:design_basis:design_basis_status> ?design_basis_status }
OPTIONAL { ?design_basis_row <urn:mara:query:column:design_basis:design_basis_edges> ?design_basis_edges }
}
}

SELECT ?root ?status ?contributor ?scenario ?validation ?validation_status ?result ?definition_revision ?applicable ?validation_edges ?validation_facts ?validation_summary ?validation_count WHERE {
?root <urn:mara:field:status> ?status .
OPTIONAL { ?contributor (<urn:mara:relation:satisfies>|<urn:mara:relation:contributes_to>) ?root }
OPTIONAL { ?validation <urn:mara:relation:validates> ?root ; <urn:mara:relation:exercises> ?scenario }
OPTIONAL { ?root <urn:mara:query:input:validation> ?validation_row .
OPTIONAL { ?validation_row <urn:mara:query:column:validation:validation> ?validation }
OPTIONAL { ?validation_row <urn:mara:query:column:validation:validation_status> ?validation_status }
OPTIONAL { ?validation_row <urn:mara:query:column:validation:result> ?result }
OPTIONAL { ?validation_row <urn:mara:query:column:validation:definition_revision> ?definition_revision }
OPTIONAL { ?validation_row <urn:mara:query:column:validation:applicable> ?applicable }
OPTIONAL { ?validation_row <urn:mara:query:column:validation:validation_summary> ?validation_summary }
OPTIONAL { ?validation_row <urn:mara:query:column:validation:validation_count> ?validation_count }
OPTIONAL { ?validation_row <urn:mara:query:column:validation:validation_edges> ?validation_edges }
OPTIONAL { ?validation_row <urn:mara:query:column:validation:validation_facts> ?validation_facts }
}
}

SELECT ?root ?status ?requirement_basis_status ?verification_status ?design_basis_status ?collision_status ?repeats_title ?relation ?target ?target_status ?compatible ?requirement_edges ?design_edges ?lifecycle_edges WHERE {
?root <urn:mara:field:status> ?status .

OPTIONAL { ?root <urn:mara:query:input:requirement> ?requirement_row .
OPTIONAL { ?requirement_row <urn:mara:query:column:requirement:requirement_basis_status> ?requirement_basis_status }
OPTIONAL { ?requirement_row <urn:mara:query:column:requirement:verification_status> ?verification_status }
OPTIONAL { ?requirement_row <urn:mara:query:column:requirement:requirement_edges> ?requirement_edges }
}
OPTIONAL { ?root <urn:mara:query:input:design> ?design_row .
OPTIONAL { ?design_row <urn:mara:query:column:design:design_basis_status> ?design_basis_status }
OPTIONAL { ?design_row <urn:mara:query:column:design:design_edges> ?design_edges }
}
OPTIONAL { ?root <urn:mara:query:input:term> ?term_row .
OPTIONAL { ?term_row <urn:mara:query:column:term:collision_status> ?collision_status }
OPTIONAL { ?term_row <urn:mara:query:column:term:repeats_title> ?repeats_title }
}
OPTIONAL { ?root <urn:mara:query:input:lifecycle> ?lifecycle_row .
OPTIONAL { ?lifecycle_row <urn:mara:query:column:lifecycle:relation> ?relation }
OPTIONAL { ?lifecycle_row <urn:mara:query:column:lifecycle:target> ?target }
OPTIONAL { ?lifecycle_row <urn:mara:query:column:lifecycle:target_status> ?target_status }
OPTIONAL { ?lifecycle_row <urn:mara:query:column:lifecycle:compatible> ?compatible }
OPTIONAL { ?lifecycle_row <urn:mara:query:column:lifecycle:lifecycle_edges> ?lifecycle_edges }
}
}

SELECT ?root ?basis ?flavour ?relation ?status ?edge WHERE {
VALUES ?view_root_flavour { <urn:mara:flavour:requirement> }
?root a ?view_root_flavour .
{ ?root <urn:mara:relation:satisfies> ?basis . BIND(<urn:mara:relation:satisfies> AS ?relation) ?edge <urn:mara:query:source> ?root ; <urn:mara:query:target> ?basis ; <urn:mara:query:relation> <urn:mara:relation:satisfies> . }
UNION { ?root <urn:mara:relation:decomposes> ?basis . BIND(<urn:mara:relation:decomposes> AS ?relation) ?edge <urn:mara:query:source> ?root ; <urn:mara:query:target> ?basis ; <urn:mara:query:relation> <urn:mara:relation:decomposes> . }
UNION { ?root <urn:mara:relation:derives_from> ?basis . BIND(<urn:mara:relation:derives_from> AS ?relation) ?edge <urn:mara:query:source> ?root ; <urn:mara:query:target> ?basis ; <urn:mara:query:relation> <urn:mara:relation:derives_from> . }
UNION { ?basis <urn:mara:relation:justifies> ?root . BIND(<urn:mara:relation:justifies> AS ?relation) ?edge <urn:mara:query:source> ?basis ; <urn:mara:query:target> ?root ; <urn:mara:query:relation> <urn:mara:relation:justifies> . }
?basis a ?flavour ; <urn:mara:field:status> ?status .
}

SELECT ?root ?basis ?flavour ?relation ?status ?edge WHERE {
VALUES ?view_root_flavour { <urn:mara:flavour:design> }
?root a ?view_root_flavour .
{ ?root <urn:mara:relation:satisfies> ?basis . BIND(<urn:mara:relation:satisfies> AS ?relation) ?edge <urn:mara:query:source> ?root ; <urn:mara:query:target> ?basis ; <urn:mara:query:relation> <urn:mara:relation:satisfies> . }
UNION { ?root <urn:mara:relation:contributes_to> ?basis . BIND(<urn:mara:relation:contributes_to> AS ?relation) ?edge <urn:mara:query:source> ?root ; <urn:mara:query:target> ?basis ; <urn:mara:query:relation> <urn:mara:relation:contributes_to> . }
UNION { ?root <urn:mara:relation:decomposes> ?basis . BIND(<urn:mara:relation:decomposes> AS ?relation) ?edge <urn:mara:query:source> ?root ; <urn:mara:query:target> ?basis ; <urn:mara:query:relation> <urn:mara:relation:decomposes> . }
?basis a ?flavour ; <urn:mara:field:status> ?status .
}

SELECT ?root ?status ?basis_status ?verification_status ?basis_support ?verification_edge WHERE {
VALUES ?view_root_flavour { <urn:mara:flavour:requirement> }
?root a ?view_root_flavour .
?root <urn:mara:field:status> ?status . OPTIONAL { ?root <urn:mara:query:input:basis> ?basis_row .
?basis_row <urn:mara:query:column:basis:status> ?basis_status . OPTIONAL { ?basis_row <urn:mara:query:column:basis:basis_support> ?basis_support } }
OPTIONAL { ?verification <urn:mara:relation:verifies> ?root ; <urn:mara:field:status> ?verification_status . ?verification_edge <urn:mara:query:source> ?verification ; <urn:mara:query:target> ?root ; <urn:mara:query:relation> <urn:mara:relation:verifies> . }
}

SELECT ?root ?status ?basis_status ?verification_status ?basis_support WHERE {
VALUES ?view_root_flavour { <urn:mara:flavour:design> }
?root a ?view_root_flavour .
?root <urn:mara:field:status> ?status . OPTIONAL { ?root <urn:mara:query:input:basis> ?basis_row .
?basis_row <urn:mara:query:column:basis:status> ?basis_status . OPTIONAL { ?basis_row <urn:mara:query:column:basis:basis_support> ?basis_support } }
}

SELECT ?root ?status ?collision_status ?repeats_title WHERE {
VALUES ?view_root_flavour { <urn:mara:flavour:term> }
?root a ?view_root_flavour .
?root <urn:mara:field:status> ?status .
BIND(EXISTS { ?root <urn:mara:query:nfc-casefold:title> ?name ; <urn:mara:query:nfc-casefold:field:aliases> ?name } AS ?repeats_title)
OPTIONAL { ?root <urn:mara:query:input:collisions> ?collisions_row .
?collisions_row <urn:mara:query:column:collisions:status> ?collision_status . }
}

SELECT ?root ?other ?status ?matched ?kind WHERE {
VALUES ?view_root_flavour { <urn:mara:flavour:term> }
?root a ?view_root_flavour .
{ ?root <urn:mara:query:nfc-casefold:title> ?matched . ?other <urn:mara:query:nfc-casefold:title> ?matched . BIND("title/title" AS ?kind) }
UNION { ?root <urn:mara:query:nfc-casefold:title> ?matched . ?other <urn:mara:query:nfc-casefold:field:aliases> ?matched . BIND("title/alias" AS ?kind) }
UNION { ?root <urn:mara:query:nfc-casefold:field:aliases> ?matched . ?other <urn:mara:query:nfc-casefold:title> ?matched . BIND("alias/title" AS ?kind) }
UNION { ?root <urn:mara:query:nfc-casefold:field:aliases> ?matched . ?other <urn:mara:query:nfc-casefold:field:aliases> ?matched . BIND("alias/alias" AS ?kind) }
?other a <urn:mara:flavour:term> ; <urn:mara:field:status> ?status . FILTER(!sameTerm(?root,?other))
}
